-- V3 TEST UPDATE: бүх тоглогч leaderboard-д орно + live chat + live tournament
create or replace function public.get_leaderboard()
returns table (rank_number bigint, player_username text, player_display_name text, player_xp integer, player_unlocked integer)
language sql security definer set search_path=public as $$
 select row_number() over(order by p.xp desc,p.created_at asc),p.username,p.display_name,p.xp,p.unlocked
 from public.profiles p where p.is_active=true order by p.xp desc,p.created_at asc limit 100;
$$;
grant execute on function public.get_leaderboard() to authenticated;

create table if not exists public.chat_messages(id bigint generated by default as identity primary key,user_id uuid not null references auth.users(id) on delete cascade,display_name text not null,message text not null check(char_length(message) between 1 and 250),created_at timestamptz not null default now());
alter table public.chat_messages enable row level security;
drop policy if exists "chat read active" on public.chat_messages; create policy "chat read active" on public.chat_messages for select to authenticated using(exists(select 1 from public.profiles p where p.id=auth.uid() and p.is_active));
drop policy if exists "chat insert own active" on public.chat_messages; create policy "chat insert own active" on public.chat_messages for insert to authenticated with check(user_id=auth.uid() and exists(select 1 from public.profiles p where p.id=auth.uid() and p.is_active));
do $$ begin alter publication supabase_realtime add table public.chat_messages; exception when duplicate_object then null; end $$;

create table if not exists public.tournaments(id bigint generated by default as identity primary key,title text not null,starts_at timestamptz not null default now(),ends_at timestamptz not null,created_by uuid references auth.users(id),created_at timestamptz default now());
create table if not exists public.tournament_scores(tournament_id bigint references public.tournaments(id) on delete cascade,user_id uuid references auth.users(id) on delete cascade,correct_count int not null default 0,wrong_count int not null default 0,elapsed_ms bigint not null default 0,joined_at timestamptz default now(),primary key(tournament_id,user_id));
alter table public.tournaments enable row level security; alter table public.tournament_scores enable row level security;

create or replace function public.get_active_tournament() returns public.tournaments language sql security definer set search_path=public as $$ select t from public.tournaments t where now() between t.starts_at and t.ends_at order by t.id desc limit 1 $$;
create or replace function public.join_tournament(p_tournament_id bigint) returns void language plpgsql security definer set search_path=public as $$ begin insert into public.tournament_scores(tournament_id,user_id) values(p_tournament_id,auth.uid()) on conflict do nothing; end $$;
create or replace function public.submit_tournament_answer(p_tournament_id bigint,p_correct boolean,p_elapsed_ms bigint) returns void language plpgsql security definer set search_path=public as $$ begin if not exists(select 1 from public.tournaments where id=p_tournament_id and now() between starts_at and ends_at) then raise exception 'Тэмцээн дууссан'; end if; insert into public.tournament_scores(tournament_id,user_id,correct_count,wrong_count,elapsed_ms) values(p_tournament_id,auth.uid(),case when p_correct then 1 else 0 end,case when p_correct then 0 else 1 end,greatest(0,p_elapsed_ms)) on conflict(tournament_id,user_id) do update set correct_count=tournament_scores.correct_count+case when p_correct then 1 else 0 end,wrong_count=tournament_scores.wrong_count+case when p_correct then 0 else 1 end,elapsed_ms=greatest(tournament_scores.elapsed_ms,greatest(0,p_elapsed_ms)); end $$;
create or replace function public.finish_tournament(p_tournament_id bigint) returns void language sql security definer set search_path=public as $$ select $$;
create or replace function public.get_tournament_leaderboard(p_tournament_id bigint) returns table(player_display_name text,correct_count int,wrong_count int,elapsed_ms bigint) language sql security definer set search_path=public as $$ select p.display_name,s.correct_count,s.wrong_count,s.elapsed_ms from public.tournament_scores s join public.profiles p on p.id=s.user_id where s.tournament_id=p_tournament_id order by s.correct_count desc,s.wrong_count asc,s.elapsed_ms asc limit 100 $$;
create or replace function public.admin_start_tournament(p_title text,p_minutes int) returns bigint language plpgsql security definer set search_path=public as $$ declare v_id bigint; begin if not exists(select 1 from public.admin_users where user_id=auth.uid()) then raise exception 'Admin эрхгүй'; end if; if p_minutes<1 or p_minutes>60 then raise exception '1-60 минут'; end if; insert into public.tournaments(title,ends_at,created_by) values(coalesce(nullif(trim(p_title),''),'Сорилын эцсийн тэмцээн'),now()+(p_minutes||' minutes')::interval,auth.uid()) returning id into v_id; return v_id; end $$;

grant execute on function public.get_active_tournament() to authenticated; grant execute on function public.join_tournament(bigint) to authenticated; grant execute on function public.submit_tournament_answer(bigint,boolean,bigint) to authenticated; grant execute on function public.finish_tournament(bigint) to authenticated; grant execute on function public.get_tournament_leaderboard(bigint) to authenticated; grant execute on function public.admin_start_tournament(text,int) to authenticated;
